#pragma once
// Numbering of the intrinsics. The port binds them under the numbers of the
// French usecode (USECODE/UNKCOFF.DAT of the French CRUSADER.EXE, 309
// entries). The US usecode (v1.23, 311 entries) calls the same routines under
// other numbers; this table gives, for each US number, the French number of
// the same routine. It was built by matching the two UNKCOFF.DAT tables both by
// ScummVM's names and by the code of the routines in the two executables.

//
// The 1.01 usecode (308 entries) has its own numbers, close to the US ones:
// v101_intrinsic_numbering.hpp, generated by scripts/gen_v101_intrinsics.py.
// Its entries without a French match are 0xFFFF (left unbound).

#include "core/data_info.hpp"

#include <cstdint>
#include <span>

namespace crusader {

// Index: number called by the US usecode; value: French number.
std::span<const std::uint16_t> us_intrinsic_numbering();

// Index: number called by the 1.01 usecode; value: French number or 0xFFFF.
std::span<const std::uint16_t> v101_intrinsic_numbering();

// The numbering of the usecode of the data `info` describes; empty for the
// French data (its own numbers).
std::span<const std::uint16_t> intrinsic_numbering(const DataInfo& info);

}  // namespace crusader
